"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[1437],{83998(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>c,frontMatter:()=>i,metadata:()=>r,toc:()=>l});var n=o(74848),a=o(28453);const i={title:"Global Top, Local Bottom",sidebar_label:"2. Global Top, Local Bottom",slug:"/beggars-bowl/global-top-local-bottom",date:new Date("2026-10-21T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"distribution",category:"\u8cc7\u672c\u8207\u9000\u51fa\u6a5f\u5236",article_tags:{zh:["\u5168\u7403\u4e0d\u5e73\u7b49","\u771f\u78ba","\u5730\u79df","\u8cc7\u672c\u6d41\u52d5","\u5206\u914d"],en:["global-inequality","factfulness","land-rent","capital-mobility","distribution"]},keywords:["World Inequality Report","elephant chart","Factfulness","labour share","global minimum tax"],summary:"An office administrator on HK$22,000 a month ranks in the global top quarter, yet after rent she cannot afford a phone. Guilt and fear steer attention downward; those who take most of the pie are never part of the comparison.",description:"An office administrator on HK$22,000 a month ranks in the global top quarter, yet after rent she cannot afford a phone. Guilt and fear steer attention downward; those who take most of the pie are never part of the comparison.",status:"published",reading_time:25,series:{id:"beggars-bowl",name:"\u5f9e\u4e5e\u4e10\u7897\u88e1\u6436\u98ef",order:2,total:6}},s="Global Top, Local Bottom",r={id:"capital-game/\u5f9e\u4e5e\u4e10\u7897\u88e1\u6436\u98ef/part2",title:"Global Top, Local Bottom",description:"An office administrator on HK$22,000 a month ranks in the global top quarter, yet after rent she cannot afford a phone. Guilt and fear steer attention downward; those who take most of the pie are never part of the comparison.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/capital-game/\u5f9e\u4e5e\u4e10\u7897\u88e1\u6436\u98ef/part2.md",sourceDirName:"capital-game/\u5f9e\u4e5e\u4e10\u7897\u88e1\u6436\u98ef",slug:"/beggars-bowl/global-top-local-bottom",permalink:"/en/docs/beggars-bowl/global-top-local-bottom",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{title:"Global Top, Local Bottom",sidebar_label:"2. Global Top, Local Bottom",slug:"/beggars-bowl/global-top-local-bottom",date:"2026-10-21T00:00:00.000Z",lang:"en",section:"sober-record",topic:"distribution",category:"\u8cc7\u672c\u8207\u9000\u51fa\u6a5f\u5236",article_tags:{zh:["\u5168\u7403\u4e0d\u5e73\u7b49","\u771f\u78ba","\u5730\u79df","\u8cc7\u672c\u6d41\u52d5","\u5206\u914d"],en:["global-inequality","factfulness","land-rent","capital-mobility","distribution"]},keywords:["World Inequality Report","elephant chart","Factfulness","labour share","global minimum tax"],summary:"An office administrator on HK$22,000 a month ranks in the global top quarter, yet after rent she cannot afford a phone. Guilt and fear steer attention downward; those who take most of the pie are never part of the comparison.",description:"An office administrator on HK$22,000 a month ranks in the global top quarter, yet after rent she cannot afford a phone. Guilt and fear steer attention downward; those who take most of the pie are never part of the comparison.",status:"published",reading_time:25,series:{id:"beggars-bowl",name:"\u5f9e\u4e5e\u4e10\u7897\u88e1\u6436\u98ef",order:2,total:6}},sidebar:"docs",previous:{title:"1. Suffer If You Don't Work?",permalink:"/en/docs/beggars-bowl/more-work-more-pay"},next:{title:"3. The Fraud You Can See",permalink:"/en/docs/beggars-bowl/visible-fraud-unmeasured-numbers"}},h={},l=[{value:"The ranking and the end of the month",id:"the-ranking-and-the-end-of-the-month",level:2},{value:"1. Where you stand",id:"1-where-you-stand",level:2},{value:"2. The same money does not buy the same life",id:"2-the-same-money-does-not-buy-the-same-life",level:2},{value:"3. How much of this position did you earn?",id:"3-how-much-of-this-position-did-you-earn",level:2},{value:"4. The first trap: guilt",id:"4-the-first-trap-guilt",level:2},{value:"5. <em>Factfulness</em>: the most respectable gag order",id:"5-factfulness-the-most-respectable-gag-order",level:2},{value:"6. The second trap: fear",id:"6-the-second-trap-fear",level:2},{value:"7. Where the money is",id:"7-where-the-money-is",level:2},{value:"8. The other side",id:"8-the-other-side",level:2},{value:"9. Protections dismantled",id:"9-protections-dismantled",level:2},{value:"Closing: one pie, cut thinner every year",id:"closing-one-pie-cut-thinner-every-year",level:2},{value:"References",id:"references",level:2}];function d(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"global-top-local-bottom",children:"Global Top, Local Bottom"})}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Why, on distribution, someone is always telling you to look down"})}),"\n",(0,n.jsx)(t.p,{children:"@Mythogen Engine \xb7 Oct 21, 2026"}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"\u201cSnatching Rice from the Beggar's Bowl\u201d, Part 2"})," | Previous: ",(0,n.jsx)(t.a,{href:"/en/docs/beggars-bowl/more-work-more-pay",children:"\u201cSuffer If You Don't Work?\u201d"})," | Next: ",(0,n.jsx)(t.a,{href:"/en/docs/beggars-bowl/visible-fraud-unmeasured-numbers",children:"\u201cThe Fraud You Can See, the Numbers Nobody Measures\u201d"})]}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.em,{children:"Not resenting the rich, not hating the poor: struggle is not competition, and in the end it reaches every floor."})}),"\n",(0,n.jsx)(t.h2,{id:"the-ranking-and-the-end-of-the-month",children:"The ranking and the end of the month"}),"\n",(0,n.jsx)(t.p,{children:"Ah Yan is thirty-two and works as an office administrator at a small company in Hong Kong, earning HK$22,000 a month. The title on her business card looks better than the number on her payslip."}),"\n",(0,n.jsxs)(t.p,{children:["One evening she tries an online \u201c",(0,n.jsx)(t.a,{href:"https://mythogenengine-cyber.github.io/AI_Studio_Rapid/",children:"global income ranking calculator"}),"\u201d. She enters her monthly pay, and the screen says she ranks in the top quarter of the world's adults. She takes a screenshot to send to a friend, then doesn't. That afternoon her landlord had told her the rent goes up next year; after rent, her pension contribution and her credit card, what is left this month is not enough for a new phone."]}),"\n",(0,n.jsx)(t.p,{children:"Under a video about the wealth gap, she comments that she has nothing left by the end of the month. The first reply: \u201cYou're already rich by global standards. Kids in Africa don't even have food, and you're complaining?\u201d The second: \u201cKeep this up and people from the Third World will flood in, and you won't even have this job.\u201d"}),"\n",(0,n.jsx)(t.p,{children:"One says she is too rich to complain; the other says she is about to be dragged down by the poor. The two replies point in opposite directions, but they share one thing: both tell her to look at people poorer than her. Neither asks where the money went."}),"\n",(0,n.jsx)(t.h2,{id:"1-where-you-stand",children:"1. Where you stand"}),"\n",(0,n.jsx)(t.p,{children:"Workers in Hong Kong, Taiwan and developed economies generally occupy an awkward position: top tier by global income, lower-middle by local living standards."}),"\n",(0,n.jsxs)(t.p,{children:["The 2026 ",(0,n.jsx)(t.em,{children:"World Inequality Report"})," lets us measure that position. The poorer half of the world's adults earn on average about \u20ac5,100 a year, or about \u20ac425 a month; the threshold for the global top 1% is about \u20ac250,000 a year. The report uses purchasing-power-parity euros, that is, euros adjusted so that prices are comparable across countries; the same applies below. The top 10% globally, about 560 million adults, take 53% of global income; the bottom 50%, about 2.8 billion people, get 8% (",(0,n.jsx)(t.a,{href:"https://wir2026.wid.world/?p=7",children:"World Inequality Report 2026"}),")."]}),"\n",(0,n.jsxs)(t.p,{children:["Ah Yan earns HK$22,000 a month, slightly below Hong Kong's median monthly employment earnings of HK$23,600 (",(0,n.jsx)(t.a,{href:"https://udn.com/news/story/7333/9585358",children:"C&SD data, reported by UDN"}),"), or about HK$260,000 a year. To compare this with those numbers, Hong Kong dollars must first be put on the same scale. At the World Bank's private-consumption PPP rate, about HK$6.06 equals one international dollar (",(0,n.jsx)(t.a,{href:"https://www.indexmundi.com/facts/hong-kong-sar%2c-china/ppp-conversion-factor",children:"World Bank data"}),"), so her annual income is worth about 44,000 international dollars; converted roughly at euro-area PPP, that is about \u20ac30,000 in PPP terms, about six times the average income of the poorer half of the world. That already makes her richer than most people on earth, yet still short of the global top 10% \u2014 the report puts that threshold at about \u20ac65,500 a year, and she is not even halfway; as for the top 1% line, her income would need to be about eight times what it is now. She is neither at the top nor in the Third World, but stuck in the middle \u2014 high on the global ranking, low on her own city's lease."]}),"\n",(0,n.jsxs)(t.p,{children:["The calculator at the start of this essay was built by this site (",(0,n.jsx)(t.a,{href:"https://mythogenengine-cyber.github.io/AI_Studio_Rapid/",children:"global income ranking calculator"}),"). Checking it while writing, I found the first version was wrong: it stitched together data on different bases into one curve and treated the report's euros as US dollars, which briefly \u201cpromoted\u201d Ah Yan into the global top 10%. After the fix, she lands in the top quarter. Same person, same pay; only the definitions changed, and the ranking moved by more than ten percentage points. A ranking looks precise to the decimal point, but behind it is a chain of choices: which currency, which basket of prices, adults or all people, before or after tax. Any income ranking, including this site's, should be asked which definitions it uses before you look at the rank it gives you."]}),"\n",(0,n.jsx)(t.p,{children:"Hong Kong has an extra layer. A family that bought early may rank high globally by wealth, and that wealth is not entirely illusory: once the mortgage is paid off there is no rent, which amounts to an extra monthly income; sell up to emigrate, downsize or move somewhere cheaper, and paper gains become real money \u2014 what Hong Kong people call \u201cmaking it ashore\u201d."}),"\n",(0,n.jsxs)(t.p,{children:["But making it ashore has two conditions: getting in early, and finding a way out. If you sell but still have to live in Hong Kong, you sell high and buy back just as high; most of the gain just goes round in a circle on paper. Late buyers are another story: prices have fallen nearly 30% from their 2021 peak, and negative-equity cases rose to more than 40,000 in Q3 2024, a 21-year high (",(0,n.jsx)(t.a,{href:"https://www.rfa.org/cantonese/news/htm/hong-kong-mortgage-negative-equity-real-estate-economy-10312024094418.html",children:"RFA"}),"); only after prices stabilised did they fall to 4,356 in Q2 2026 (",(0,n.jsx)(t.a,{href:"https://www.hkma.gov.hk/chi/news-and-media/press-releases/2026/07/20260731-6/",children:"HKMA"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"The same flat is wealth for those who got in early and found the exit; for those who bought at the peak on a full mortgage, it may be a negative number. This kind of wealth depends on when you got in and which door you leave by, not on what is left at the end of the month \u2014 as with another, much larger paper fortune discussed below."}),"\n",(0,n.jsxs)(t.p,{children:["Taiwan's version comes from another report. Allianz's ",(0,n.jsx)(t.em,{children:"Global Wealth Report 2026"})," shows Taiwan's net financial assets per capita in 2025 at \u20ac164,470, about NT$5.94 million, fifth in the world after the US, Switzerland, Denmark and Singapore (",(0,n.jsx)(t.a,{href:"https://focustaiwan.tw/business/202610010004",children:"Focus Taiwan"}),"). When the news came out, people online split into two camps: one said Taiwan turns out to be so rich, the other said they felt nothing of the kind. Finance writer Wang Po-ta took the report apart on Facebook and argued both camps were right, because the \u201cfeeling nothing\u201d has three layers."]}),"\n",(0,n.jsxs)(t.p,{children:["The first layer is distribution. The richest tenth of Taiwanese hold about 60% of financial assets (",(0,n.jsx)(t.a,{href:"https://news.cnyes.com/news/id/6177446",children:"cnyes"}),"). Using the report appendix's figure of 61.8%, Wang calculated that the richest tenth average about NT$36.7 million each, while the other nine-tenths average about NT$2.52 million, less than half of NT$5.94 million. And NT$2.52 million is still a mean; the median of those nine-tenths can only be lower."]}),"\n",(0,n.jsxs)(t.p,{children:["The second layer is debt. Taiwanese household debt rose 6.3% in 2025 to \u20ac714.2 billion (",(0,n.jsx)(t.a,{href:"https://www.businesstoday.com.tw/article/category/183025/post/202610020019/",children:"Business Today"}),"). The report counts mortgages as liabilities but does not count homes as assets; a young family that has just taken on a NT$10 million mortgage with a few hundred thousand in savings may have negative net financial assets in the report. What they feel every month is the mortgage side."]}),"\n",(0,n.jsxs)(t.p,{children:["The third layer is stock versus flow. The NT$5.94 million measures a stock built up over decades of saving plus rising asset prices, not income earned each year. Allianz itself notes that of every \u20ac5 of new household wealth worldwide in 2025, about \u20ac4 came from rising asset prices, while new global savings actually fell 5.4% (",(0,n.jsx)(t.a,{href:"https://www.gvm.com.tw/article/133444",children:"Global Views"}),"). Taiwanese households' securities rose 17.7% in a year, while deposits rose only 4.9% (",(0,n.jsx)(t.a,{href:"https://www.businesstoday.com.tw/article/category/183025/post/202610020019/",children:"Business Today"}),"). Those with shares saw their wealth take off with the market; for those saving from wages, fifth place has little to do with them."]}),"\n",(0,n.jsx)(t.p,{children:"The Hong Kong and Taiwan versions say the same thing: rankings measure stocks and averages, while life is lived in flows and medians. Ah Yan's place on the global ranking and the balance in her account at the end of the month are two different numbers."}),"\n",(0,n.jsx)(t.h2,{id:"2-the-same-money-does-not-buy-the-same-life",children:"2. The same money does not buy the same life"}),"\n",(0,n.jsx)(t.p,{children:"Purchasing power parity solves one problem and creates another. It evens out prices across countries so that a dollar in Hong Kong can be compared with one in Bangladesh; but it uses a national average basket of goods, weighted by the whole society's spending. Ah Yan's basket is not the average basket. At the HK$9,000 to HK$12,000 a month that people online often quote for a 200 sq ft flat, rent already takes 40% to half of her pay; the average basket does not give rent more weight because she hands half her income to a landlord."}),"\n",(0,n.jsxs)(t.p,{children:["Only over a longer span can you see how that basket has grown heavier. In 2000, Hong Kong's median monthly employment earnings were HK$10,000 (",(0,n.jsx)(t.a,{href:"https://www.stats.gov.cn/sj/ndsj/2005/html/W2409C.HTM",children:"Hong Kong data reprinted in China's National Bureau of Statistics yearbook"}),"); for February to April this year it is HK$23,600 (",(0,n.jsx)(t.a,{href:"https://udn.com/news/story/7333/9585358",children:"UDN"}),"), a rise of about 140% over two decades. Over the same period, the Rating and Valuation Department's private domestic price index, with 1999 as 100 (",(0,n.jsx)(t.a,{href:"https://www.syfe.com/hk/magazine/zh-hant/%E9%A6%99%E6%B8%AF-%E6%A8%93-%E5%83%B9-%E6%8C%87%E6%95%B8/",children:"Syfe"}),"), stood at 323.2 in June this year and peaked at 398.1 in September 2021 (",(0,n.jsx)(t.a,{href:"https://www.stheadline.com/realtime-property/3598729/",children:"Sing Tao"}),"): prices more than tripled, and at the peak came close to quadrupling."]}),"\n",(0,n.jsxs)(t.p,{children:["The rent story is more complicated. In the same index series, rents reached 205.8 in June this year, a record (",(0,n.jsx)(t.a,{href:"https://www.stheadline.com/realtime-property/3598729/",children:"Sing Tao"}),"), about double 1999 \u2014 a rise similar to wages. But that doubling started from an already very high base: wages and rents rose together, so rent's share of income did not fall, while the threshold for buying moved further away."]}),"\n",(0,n.jsxs)(t.p,{children:["A plate of baked pork chop rice tells a different story. In 1984, Fairwood sold baked pork chop rice for HK$8.50 (",(0,n.jsx)(t.a,{href:"https://www.hk01.com/%E7%86%B1%E7%88%86%E8%A9%B1%E9%A1%8C/293987/35%E5%B9%B4%E5%89%8D%E5%A4%A7%E5%BF%AB%E6%B4%BB%E9%A4%90%E7%89%8C%E6%9B%9D%E5%85%89-%E6%9C%80%E5%B9%B3%E7%A2%9F%E9%A0%AD%E9%A3%AF6-5%E5%85%83%E6%9C%89%E4%BA%A4%E6%98%93-%E4%B8%80%E7%A2%97%E6%B9%AF%E5%8F%88%E5%B9%BE%E9%8C%A2",children:"HK01"}),"); on a 2010 Fairwood menu, the pork chop rice with a drink was HK$35; in 2026 a Fairwood rice plate with tea or a soft drink, such as the chilli chicken rice, costs HK$58, or HK$64 with the slow-cooked soup. Over the later part of that period, median employment earnings rose from HK$11,000 in 2010 (",(0,n.jsx)(t.a,{href:"https://www.stats.gov.cn/sj/ndsj/2012/html/W2409C.HTM",children:"Hong Kong data reprinted in China's National Bureau of Statistics yearbook"}),") to HK$23,600 this year. In other words, a month's median pay bought about 310 plates in 2010 and about 400 now. In Hong Kong, food has actually become relatively cheaper; what has outrun wages is property."]}),"\n",(0,n.jsx)(t.p,{children:"But there is a gap in this number that statistics cannot see. Many Hong Kong people feel that fast food has become more expensive, worse-tasting and smaller; the HK$8.50 plate of 1984 was cooked from real ingredients in a kitchen, while today's rice plate tastes more like a pre-made product heated in the shop. A price index measures the price of a plate, not what is missing from it. The Taiwan Railway pork chop bento mentioned below, still NT$60 but with a shrunken chop and fewer sides, is the same thing: the price hasn't changed, what's inside the box has. So \u201ca month's pay buys 400 plates\u201d is only half right \u2014 it buys plates, not necessarily the plate of those days; the big fall in quality and quantity is not counted."}),"\n",(0,n.jsxs)(t.p,{children:["Taiwan's numbers make the gap even clearer. In 2025, average regular monthly earnings of Taiwanese employees were NT$47,884, up 3.09%, the largest rise in 26 years; after inflation, real regular earnings rose 1.4% (",(0,n.jsx)(t.a,{href:"https://finance.technews.tw/2026/02/11/2025-salary-47884ntd/",children:"TechNews citing DGBAS"}),"). But the same statistics show nearly 70% of employees earning below the average; median regular earnings are only about NT$38,319 (",(0,n.jsx)(t.a,{href:"https://news.pts.org.tw/article/785293",children:"PTS"}),")."]}),"\n",(0,n.jsxs)(t.p,{children:["Over a longer span, Taiwan's wages look more like standing still. In December 2018, real regular monthly earnings after inflation were NT$38,235, lower than NT$38,398 in 2001 \u2014 back 17 years (",(0,n.jsx)(t.a,{href:"https://news.tvbs.com.tw/life/1085883",children:"TVBS"}),"). Over the same period, Taipei's house-price-to-income ratio rose from about 6 in 2002 (",(0,n.jsx)(t.a,{href:"https://www.gvm.com.tw/article/88701",children:"Global Views"}),") to 15.57 in Q1 2025 (",(0,n.jsx)(t.a,{href:"https://money.udn.com/money/story/5621/8984160",children:"Economic Daily News"}),"): two decades ago, a Taipei household could buy a median home with six years of income, spending nothing; now it takes fifteen and a half."]}),"\n",(0,n.jsxs)(t.p,{children:["Memories of living costs often live in a lunch box. People online recall that a Fulong bento once cost NT$50\u201360 and now costs NT$90 (",(0,n.jsx)(t.a,{href:"https://udn.com/news/story/120912/9640775",children:"United Daily News"}),"); Taiwan Railway's classic NT$60 pork chop bento is still around, but the chop, sides and rice have all shrunk, and it is sold in limited numbers (",(0,n.jsx)(t.a,{href:"https://www.taiwannews.com.tw/zh/news/6089701",children:"Taiwan News"}),"); office workers in the north have long complained that they cannot find a bento under NT$100 (",(0,n.jsx)(t.a,{href:"https://www.chinatimes.com/realtimenews/20211119001248-260405",children:"China Times"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"The bento went from NT$50\u201360 to nearly NT$100, a rise of over 50%; real wages are about where they were in 2001; and a Taipei home went from six years of income to more than fifteen. Wages keep up with the official average price level; they do not keep up with bentos, leases and house prices."}),"\n",(0,n.jsxs)(t.p,{children:["Prices have two sets of books too. Taiwan's consumer price index rose only 1.66% in 2025, but taking June that year as an example, CPI rose 1.37% year on year, a 51-month low, while food rose 2.82% and eating out 3.44% (",(0,n.jsx)(t.a,{href:"https://news.tvbs.com.tw/news/searchresult/%E4%B8%BB%E8%A8%88%E7%B8%BD/news/4",children:"TVBS"}),"); the housing index and rent index both hit record highs. House prices are another order of magnitude: from 2018 to 2024, the Ministry of the Interior's housing price index and the Sinyi index rose an average of 6.58% and 8.12% a year, far above overall CPI and rents; Academia Sinica calls the gap between official figures and what people experience \u201cfelt prices\u201d (",(0,n.jsx)(t.a,{href:"https://www.nownews.com/news/6703220",children:"NOWnews citing Academia Sinica"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"Official inflation measures the average person's inflation. The lower someone's income, the larger the share of eating out and rent in their spending, and the closer the inflation they feel is to bentos and leases rather than the average 1.66%. Pay up 3%, bentos and rent up 3% to 4%, house prices up 7% a year \u2014 on the global ranking, their place does not move at all; in their own city, a home drifts further away."}),"\n",(0,n.jsx)(t.p,{children:"Price and wage levels in Hong Kong and Taiwan differ a great deal: both are high in Hong Kong and both low in Taiwan. What the two share is not the level but the direction: wages follow average inflation, while living costs follow rent and eating out. Global rankings use purchasing power to even out the world, but the lives of Ah Yan and that Taiwanese worker are counted in leases and menus."}),"\n",(0,n.jsx)(t.h2,{id:"3-how-much-of-this-position-did-you-earn",children:"3. How much of this position did you earn?"}),"\n",(0,n.jsx)(t.p,{children:"Ah Yan is richer than most people in Africa mainly not because she works harder than they do, but because of where she was born."}),"\n",(0,n.jsxs)(t.p,{children:["The economist Branko Milanovi\u0107 ran a calculation: suppose everyone has only two characteristics they can barely control \u2014 which country they live in, and which income class they belong to within it. These two alone explain more than half of global income inequality; his conclusion is that effort or luck can play only a limited role in the global income distribution (",(0,n.jsx)(t.a,{href:"https://ideas.repec.org/a/tpr/restat/v97y2015i2p452-460.html",children:"Milanovi\u0107, 2015"}),"). He calls the income gap that comes with birthplace a \u201ccitizenship premium\u201d or \u201ccitizenship rent\u201d (",(0,n.jsx)(t.a,{href:"https://demos.org/blog/income-inequality-interview-branko-milanovic",children:"Demos interview"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"The idea has an uncomfortable symmetry. We generally dislike the children of the rich \u2014 within one country, inheriting wealth by birth is seen as unfair. But across countries, \u201cinheriting\u201d an income several times higher by birthplace is something few people feel they need to justify."}),"\n",(0,n.jsx)(t.p,{children:"This is not meant to make Ah Yan feel guilty. The citizenship premium describes two sides of the same thing: if most of her position is luck, then most of the position of someone her age in Africa is luck too. That being so, explaining either side's situation by \u201chard work\u201d or \u201claziness\u201d does not hold up."}),"\n",(0,n.jsx)(t.h2,{id:"4-the-first-trap-guilt",children:"4. The first trap: guilt"}),"\n",(0,n.jsx)(t.p,{children:"\u201cYou're already rich by global standards, why complain?\u201d sounds like a moral reminder; its real function is to make people shut up."}),"\n",(0,n.jsx)(t.p,{children:"Its logic: as long as someone in the world is worse off than you, you have no right to complain. Follow this logic and no one can ever complain, because someone is always worse off; in the end the only person entitled to complain is the poorest person in the world \u2014 who is not online."}),"\n",(0,n.jsx)(t.p,{children:"The effect of this trap is to swap a local question of distribution for a global competition in misery. Ah Yan's question was: why is there no money left after rent? Those who answered changed it to: how much better off are you than Africans? The first question points to landlords, land prices, wages and the tax system; the second points only to her own conscience."}),"\n",(0,n.jsx)(t.p,{children:"Guilt will not give that child in Africa an extra meal either. If Ah Yan holds back her complaints, her rent will not go down and Africa will not get more food; the only change is that no one is left asking about distribution at home."}),"\n",(0,n.jsxs)(t.h2,{id:"5-factfulness-the-most-respectable-gag-order",children:["5. ",(0,n.jsx)(t.em,{children:"Factfulness"}),": the most respectable gag order"]}),"\n",(0,n.jsx)(t.p,{children:"The guilt trap has a most respectable version, written up as an international bestseller."}),"\n",(0,n.jsxs)(t.p,{children:["In 2018, Swedish physician Hans Rosling, with his son Ola Rosling and daughter-in-law Anna Rosling R\xf6nnlund, published ",(0,n.jsx)(t.em,{children:"Factfulness"}),". Bill Gates called it one of the best books he had ever read and announced he would give a copy to every US college graduate that year (",(0,n.jsx)(t.a,{href:"https://en.wikipedia.org/wiki/Factfulness",children:"Wikipedia"}),"). The book's argument is simple: the world is much better than you think; you think it is getting worse because ten instincts distort your judgment."]}),"\n",(0,n.jsx)(t.p,{children:"The book gets some things right. It rejects dividing the world into \u201cus\u201d and \u201cthem\u201d, and reminds readers that people in poor countries are making progress too \u2014 on this, this essay agrees. The problem lies in what it cannot see, and that happens to be Ah Yan's end of the month."}),"\n",(0,n.jsxs)(t.p,{children:["First, its ruler stops at the top. ",(0,n.jsx)(t.em,{children:"Factfulness"})," divides the world into four income levels: under $2 a day is Level 1, $2\u20138 Level 2, $8\u201332 Level 3, and over $32 Level 4 (",(0,n.jsx)(t.a,{href:"https://en.wikipedia.org/wiki/Factfulness",children:"Wikipedia"}),"). Level 4 has no upper limit. Ah Yan, on HK$22,000 a month, earns about $90 a day and is Level 4; Musk, whose fortune grew by more than $500 billion in a year, is also Level 4. A ruler whose markings stop at $32 can measure how Level 1 rises to Level 2, but cannot measure that inside Level 4 one person has nothing left after rent while another becomes richer overnight than 3.8 billion people combined. Where the distribution problem is most extreme is exactly this ruler's blind spot."]}),"\n",(0,n.jsx)(t.p,{children:"Second, it counts only what can be counted. Income, life expectancy, vaccination rates and school enrolment are all improving; but a plate of baked pork chop rice getting smaller and worse, a Taiwan Railway bento shrinking, a month's pay buying more plates with less on each \u2014 none of this appears in its charts. When progress is defined as what can be measured, decline that cannot be measured is as good as not having happened."}),"\n",(0,n.jsxs)(t.p,{children:["Third, it turns structural problems into psychological bias. ",(0,n.jsx)(t.em,{children:"Factfulness"})," says people think the world is getting worse because ten instincts, such as the \u201cnegativity instinct\u201d and the \u201cfear instinct\u201d, are at work. As a framework for checking headlines, this is useful; but applied to Ah Yan it becomes something else: her frustration with her lease and wages is renamed a cognitive bias to be corrected. The problem is not landlords, land prices and distribution, but her head."]}),"\n",(0,n.jsxs)(t.p,{children:["Fourth, its poverty line is itself contested. The book's progress story relies on the World Bank's extreme-poverty line of about $2 a day. In 2019 the anthropologist Jason Hickel wrote a rebuttal to Bill Gates arguing that the line is absurdly low; using a more reasonable line of $7.40 a day, the number of poor people has risen rather than fallen since 1981, and the share has stayed around 60% (",(0,n.jsx)(t.a,{href:"https://www.theguardian.com/commentisfree/2019/jan/29/bill-gates-davos-global-poverty-infographic-neoliberal",children:"The Guardian"}),"). Hickel's calculations were in turn disputed by Steven Pinker, Max Roser and others (",(0,n.jsx)(t.a,{href:"https://reason.com/2019/01/31/global-poverty-decline-denialism/",children:"Reason"}),"); but the dispute itself shows that how much better the world is getting depends on where you draw the line."]}),"\n",(0,n.jsxs)(t.p,{children:["Finally, look at who is recommending it. The person who gave this book to every US graduate is one of the richest people in the world. That does not make the book wrong, but it shows one thing: the story that \u201cthe world is getting better\u201d suits those at the top particularly well \u2014 it directs attention to progress at the very bottom rather than to the share at the top. Hickel describes Gates and Pinker as going so far as to argue that, since the same forces bringing the rich enormous wealth are also eliminating poverty, people should not complain about rising inequality (",(0,n.jsx)(t.a,{href:"https://www.theguardian.com/commentisfree/2019/jan/29/bill-gates-davos-global-poverty-infographic-neoliberal",children:"The Guardian"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"\u201cThe world is getting better\u201d and \u201cmy end of the month is getting worse\u201d can both be true. When the first is used to deny the second, data becomes a tool for silencing people \u2014 and the most respectable kind."}),"\n",(0,n.jsx)(t.h2,{id:"6-the-second-trap-fear",children:"6. The second trap: fear"}),"\n",(0,n.jsx)(t.p,{children:"The second reply has a fuller version that circulates widely online: rich countries send medicine and food to poor countries; death rates fall and populations explode, but no matching industries develop; poor countries keep producing poor people, who then flood into rich countries and drag down their living standards."}),"\n",(0,n.jsx)(t.p,{children:"The story is vivid, but several key links in it run against the data."}),"\n",(0,n.jsxs)(t.p,{children:["First, the poor are not growing in number. On the $3-a-day poverty line, the number of people in extreme poverty worldwide fell from about 2.3 billion in 1990 to about 831 million in 2025 (",(0,n.jsx)(t.a,{href:"https://www.worldbank.org/poverty",children:"World Bank"}),"); on the old $2.15 line, the share fell from nearly 38% in 1990 to an estimated 8.5% in 2024. Of course, the World Bank's lines are low; critics note that at $5 a day four in ten people are still poor, and that excluding China, the number of poor in sub-Saharan Africa has risen (",(0,n.jsx)(t.a,{href:"https://www.cadtm.org/Measuring-global-poverty",children:"CADTM"}),"). \u201cThe whole world is getting better\u201d is not the whole truth; but neither is \u201cpoor countries are breeding themselves ever poorer, ever faster\u201d."]}),"\n",(0,n.jsxs)(t.p,{children:["Second, fertility in poor countries is falling too. Sub-Saharan Africa's fertility rate peaked near 6.8 in the late 1970s and has fallen since (",(0,n.jsx)(t.a,{href:"https://fred.stlouisfed.org/data/SPDYNTFRTINSSF",children:"World Bank data"}),"); Africa as a whole was about 4.0 by 2024 (",(0,n.jsx)(t.a,{href:"https://database.earth/population/africa/fertility-rate",children:"UN World Population Prospects 2024"}),"). Slower than Asia, but in the same direction."]}),"\n",(0,n.jsxs)(t.p,{children:["Third, aid is too small to explain rich countries' difficulties. In 2024, official development assistance from OECD Development Assistance Committee members totalled $212.1 billion, just 0.33% of their gross national income (",(0,n.jsx)(t.a,{href:"https://www.oecd.org/en/about/news/press-releases/2025/04/official-development-assistance-2024-figures.html",children:"OECD"}),"). A country giving away a third of one per cent of its income is not enough to leave its own workers with nothing after rent."]}),"\n",(0,n.jsx)(t.p,{children:"The most ironic thing about this story is its own mechanism. It says the poor have many children because they lack social security and rely on their children in old age. Then the answer should be social security \u2014 once people no longer need many children to secure their old age, fertility falls. The fear story points at the poor, but its own mechanism points to protection."}),"\n",(0,n.jsx)(t.p,{children:"The same logic has a local Hong Kong version: tightening welfare on one side, importing foreign labour on the other (see Part 1 of this series, \u201cSuffer If You Don't Work?\u201d). Both start from the very bottom, while land prices and assets stay untouched."}),"\n",(0,n.jsx)(t.h2,{id:"7-where-the-money-is",children:"7. Where the money is"}),"\n",(0,n.jsxs)(t.p,{children:["Both traps tell people to look down. Look up, and the numbers are these: the richest 10% globally own 75% of the world's wealth, the poorest 50% only 2%; the richest 1% own 37%, more than eighteen times the poorer half (",(0,n.jsx)(t.a,{href:"https://wir2026.wid.world/?p=7",children:"World Inequality Report 2026"}),"). New wealth is shared the same way: from 1995 to 2021, 38% of new global wealth went to the richest 1%, while the poorest 50% got 2% (",(0,n.jsx)(t.a,{href:"https://wir2022.wid.world/www-site/uploads/2022/01/Summary_WorldInequalityReport2022_English.pdf",children:"World Inequality Report 2022"}),")."]}),"\n",(0,n.jsxs)(t.p,{children:["Most of this wealth exists as assets. In the US, the richest 10% of households hold 87.4% of household stocks and funds; the top 1%'s share rose from 42.8% in 1989 to 50.2% in 2026, with the rise concentrated in the top 0.1% (",(0,n.jsx)(t.a,{href:"https://pennycalc.com/stock-market-ownership/history/",children:"Federal Reserve Distributional Financial Accounts, compiled"}),"). Rising productivity, rising profits and rising share prices all end up in the hands of those who own shares."]}),"\n",(0,n.jsxs)(t.p,{children:["Beyond wealth, income is flowing the same way. US Bureau of Labor Statistics data show that in Q2 this year, the share of nonfarm business output paid to workers as compensation was just 52.8%, the lowest since records began in 1947; for most of the postwar period it stayed between 60% and 66% (",(0,n.jsx)(t.a,{href:"https://www.bls.gov/opub/ted/2026/labor-share-at-its-lowest-level-52-8-percent-in-second-quarter-2026.htm",children:"BLS"}),"). Over the same period productivity has been rising: up 2.9% year on year in Q1 this year, in step with the surge in AI investment; the job platform Indeed's research arm suggests these productivity gains may be shifting from workers to investors and business owners (",(0,n.jsx)(t.a,{href:"https://www.hiringlab.org/?p=20542",children:"Indeed Hiring Lab"}),"). Efficiency is up, while workers' share has fallen to its lowest in more than seventy years."]}),"\n",(0,n.jsxs)(t.p,{children:["Taiwan has a similar curve. Employee compensation as a share of GDP was above 50% in the early 1990s and fell to 43.1% in 2024, a record low; in the same year, operating surplus, which reflects corporate profits, rose to 35.06% (",(0,n.jsx)(t.a,{href:"https://money.udn.com/money/story/124921/9656403",children:"Economic Daily News"}),"). Explanations differ. DGBAS attributes it mainly to industrial structure: in capital-intensive industries such as semiconductors, much of the value added goes to equipment depreciation, so even with high engineers' pay, labour's share is low (",(0,n.jsx)(t.a,{href:"https://finance.technews.tw/2024/05/02/electronics-workers-share-economic-fruits/",children:"TechNews"}),"); Academia Sinica academician Hsieh Chang-tai argues that a long-weak New Taiwan dollar has shifted the gains of growth to the owners of exporting firms (",(0,n.jsx)(t.a,{href:"https://www.storm.mg/article/11092937",children:"Storm Media"}),"). Other research finds that the gap between real wages and productivity in 2002\u20132014 came mainly from export prices falling relative to consumer prices, rather than from changes in labour's share (",(0,n.jsx)(t.a,{href:"https://ideas.repec.org/p/sin/wpaper/17-a012.html",children:"Lin Yi-ling and Yang Tzu-ting"}),"). The explanations vary, but the direction of the numbers is not in dispute: labour's share of the economy's gains has never been smaller in recent years."]}),"\n",(0,n.jsxs)(t.p,{children:["The most extreme example came in June this year. With SpaceX's listing, Musk's fortune briefly passed $1 trillion; Oxfam calculated that at that point he alone would be richer than the poorest 46% of the world combined, about 3.8 billion people, whose total net worth is about $890 billion (",(0,n.jsx)(t.a,{href:"https://www.oxfam.org/en/node/25365",children:"Oxfam"}),"). His fortune had grown by more than $550 billion over the previous year (",(0,n.jsx)(t.a,{href:"https://www.oxfamireland.org/press/soon-to-be-trillionaire-elon-musks-wealth-grew-by-over-1-million-per-minute-in-the-last-year",children:"Oxfam Ireland"}),"); soon after the listing it fell back with the market, and the title of trillionaire lasted only a short time (",(0,n.jsx)(t.a,{href:"https://www.ibtimes.co.uk/elon-musk-trillionaire-spacex-ipo-analysis-1805312",children:"IBTimes"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"Over $500 billion more in a year came from valuation, not labour; the fall did not require him to do more or less of anything either. This is financialised wealth: it can exceed the combined wealth of 3.8 billion people overnight and lose a chunk within weeks, and neither has anything to do with how much work he did that year."}),"\n",(0,n.jsxs)(t.p,{children:["The same analysis adds one more line: a tenth of Musk's fortune would be enough to end extreme poverty worldwide (",(0,n.jsx)(t.a,{href:"https://www.oxfam.org/en/node/25365",children:"Oxfam"}),"). Improving the lot of the poorest does not require Ah Yan to be downgraded. The room is at the very top, not in the middle."]}),"\n",(0,n.jsx)(t.h2,{id:"8-the-other-side",children:"8. The other side"}),"\n",(0,n.jsx)(t.p,{children:"In fairness, two objections deserve to be taken seriously."}),"\n",(0,n.jsx)(t.p,{children:"The first comes from moral philosophy. The philosopher Peter Singer and others argue that by global standards, the middle class in rich places is genuinely rich, and so has a duty to help those poorer; \u201cthe money is at the top\u201d cannot be a reason for the middle to do nothing. The argument has force: Ah Yan is not Musk, but what she spends on takeaway each month might be a month's income for a family in extreme poverty."}),"\n",(0,n.jsx)(t.p,{children:"The second comes from economics. Globalisation has indeed exposed workers in some rich places to competition. The \u201celephant curve\u201d of economists Lakner and Milanovi\u0107 showed that from 1988 to 2008, incomes of the global middle rose sharply while the lower-middle classes of rich countries sat in a trough, which was for a time read as stagnation for those classes."}),"\n",(0,n.jsxs)(t.p,{children:["But that reading was later questioned. The UK's Resolution Foundation reanalysed the same data and argued that the claim of general stagnation among the lower-middle classes of rich countries does not hold; the problem lies mainly in especially unequal growth in the US (",(0,n.jsx)(t.a,{href:"https://www.resolutionfoundation.org/comment/blind-men-and-the-elephant-what-does-the-elephant-curve-really-tell-us-about-rich-countries/",children:"Resolution Foundation"}),"); the US think tank PIIE also noted that the trough comes largely from the collapse of the Soviet Union and Japan's stagnation, not from globalisation itself (",(0,n.jsx)(t.a,{href:"https://piie.com/blogs/realtime-economic-issues-watch/deconstructing-branko-milanovics-elephant-chart-does-it-show",children:"PIIE"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"The two objections can stand together, and both point to the same place. The pressure of globalisation is real, but on whom it falls and how hard depends on how each country distributes; the middle does have a duty to those poorer, but that duty and the top's duty to everyone differ in scale by a factor of far more than a thousand. Admitting that you are relatively well off does not mean shouldering the share that belongs to those at the top."}),"\n",(0,n.jsxs)(t.p,{children:["The problem is that how each place distributes is increasingly out of its own hands. Capital finds its own way out: factories can move, profits can be shifted to low-tax places; even after weighing political risk, it still flows globally. People cannot move that fast: they have rent, children's schooling, parents to care for. So any place that tightens on its own, whether through antitrust, labour protection or taxes on capital, hears the same line: tighten, and capital leaves (on how the tax base is hollowed out as a result, see section 13 of Part 1). In 2021, more than 130 jurisdictions agreed to a 15% global minimum corporate tax (the OECD's \u201cPillar Two\u201d) precisely to close this route; in January 2026 the OECD agreed a \u201cside-by-side\u201d arrangement exempting US multinationals from most of the rules (",(0,n.jsx)(t.a,{href:"https://kpmg.com/us/en/taxnewsflash/news/2026/01/oecd-agreement-pillar-two-side-by-side-package.html",children:"KPMG"}),", ",(0,n.jsx)(t.a,{href:"https://taxnews.ey.com/news/2026-0115-breaking-tax-news-oecd-releases-side-by-side-arrangement-exempting-us-multinationals-from-most-pillar-two-global-minimum-tax-rules",children:"EY"}),"). Even a 15% floor had to open a door for the largest source of capital."]}),"\n",(0,n.jsx)(t.p,{children:"But one thing cannot move: land. Land prices, public housing and public markets are exactly what a local government can act on without waiting for any global agreement."}),"\n",(0,n.jsx)(t.h2,{id:"9-protections-dismantled",children:"9. Protections dismantled"}),"\n",(0,n.jsxs)(t.p,{children:["At this point it is easy to conclude: if the problem is distribution, the answer is to hand out more money. But Hong Kong once had another answer: not handing out money, but holding down the cost of living structurally. In 2024, 29.4% of Hong Kong's population lived in public rental housing and 15.3% in subsidised sale flats, together nearly half (",(0,n.jsx)(t.a,{href:"https://www.hb.gov.hk/tc/publications/housing/HIF2025.pdf",children:"Housing Bureau"}),"). This was a universal protection on living costs: a ceiling on private housing, a ladder onto the market, and no need for the government to hand out cash to every household."]}),"\n",(0,n.jsxs)(t.p,{children:["Taiwan took another road. Government-built social housing totals about 127,000 units (",(0,n.jsx)(t.a,{href:"https://cna.com.tw/news/aipl/202608070274.aspx",children:"CNA citing the National Land Management Agency, end-July 2026"}),"), against a total housing stock of about 9.576 million homes (",(0,n.jsx)(t.a,{href:"https://ec.ltn.com.tw/article/breakingnews/5446842",children:"Liberty Times"}),"): under 1.5% of the stock. Taiwan relies on home ownership and family: the household home-ownership rate in 2025 was 83.95%, a 16-year low (",(0,n.jsx)(t.a,{href:"https://money.udn.com/money/amp/story/5621/9707866",children:"Economic Daily News citing DGBAS"}),"). One relies on public housing, the other on ownership; when a Taipei home takes fifteen and a half years of income, both roads are starting to clog."]}),"\n",(0,n.jsx)(t.p,{children:"How Hong Kong's protection was dismantled, how income limits screen out ordinary workers, and why the means test can measure only payslips is the subject of Part 3 of this series. Here, one point is enough: holding down living costs requires structure, and the biggest item in that structure is land rent. Dismantle the structure and patch it with cash handouts, and the money ends up flowing to land rent. The question to ask is who collects that rent."}),"\n",(0,n.jsx)(t.h2,{id:"closing-one-pie-cut-thinner-every-year",children:"Closing: one pie, cut thinner every year"}),"\n",(0,n.jsx)(t.p,{children:"Back to Ah Yan's two replies. One tells her to feel guilty about her position, the other to be afraid for it; both tell her to look at people poorer than her, so her gaze stops at children in Africa and migrants flooding in, and she never asks where the money went: to that \u20ac250,000-a-year line, let alone to the man who gained more than $500 billion in a year."}),"\n",(0,n.jsx)(t.p,{children:"The question is not whether to compare upward or downward. The whole structure sends money to the top, and the share left below shrinks every year; yet the media, society and everyone in it naturally compare only with the people beside them: the neighbour upstairs, the neighbour downstairs, colleagues, newcomers, families on welfare. However they compare, they are fighting over the same pie, cut thinner every year. This is not competition but zero-sum struggle: every extra bite you take is a bite your neighbour loses; and those who took most of the pie are never part of the comparison."}),"\n",(0,n.jsx)(t.p,{children:"Even the people the public sees as \u201cthe rich\u201d are mostly not at the top. Small and medium business owners, factory owners and shopkeepers in traditional trades are \u201cabove\u201d in workers' eyes; but they too pay rent, and depend on the goodwill of landlords, banks and platforms, their profits whittled away layer by layer by rent, commissions and price pressure from big clients. Workers think the boss is stingy, the boss thinks workers don't try hard enough, and each treats the other as their problem; in fact both are stuck on the same pie, just sitting in different places."}),"\n",(0,n.jsx)(t.p,{children:"Once the structure is clear, the questions change: productivity has risen so much, why haven't wages kept up? Assets have appreciated so much, why has it all landed with those who own assets? Improving the lot of the poorest needs only a small part of the top, so why should it be borne by the middle and the bottom fighting each other?"}),"\n",(0,n.jsx)(t.p,{children:"Population size was never the reason Ah Yan has nothing left after rent. Distribution is."}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"\u201cSnatching Rice from the Beggar's Bowl\u201d series"}),": ",(0,n.jsx)(t.a,{href:"/en/docs/beggars-bowl",children:"Prologue"})," | ",(0,n.jsx)(t.a,{href:"/en/docs/beggars-bowl/more-work-more-pay",children:"Part 1 \u201cSuffer If You Don't Work?\u201d"})," | ",(0,n.jsx)(t.strong,{children:"Part 2 \u201cGlobal Top, Local Bottom\u201d"})," | ",(0,n.jsx)(t.a,{href:"/en/docs/beggars-bowl/visible-fraud-unmeasured-numbers",children:"Part 3 \u201cThe Fraud You Can See, the Numbers Nobody Measures\u201d"})," | ",(0,n.jsx)(t.a,{href:"/en/docs/beggars-bowl/those-who-leave-and-arrive",children:"Part 4 \u201cThose Who Leave and Those Who Arrive\u201d"})," | ",(0,n.jsx)(t.a,{href:"/en/docs/beggars-bowl/after-the-counting",children:"Final part \u201cAfter the Counting\u201d"})]}),"\n",(0,n.jsx)(t.p,{children:"The next essay asks: why would a protection that worked for decades fail for no stated reason, while official figures cannot say why?"}),"\n",(0,n.jsx)(t.h2,{id:"references",children:"References"}),"\n",(0,n.jsxs)(t.p,{children:["The full list of sources is linked inline throughout; Chinese-language sources keep their original links. Key references: ",(0,n.jsx)(t.a,{href:"https://wir2026.wid.world/?p=7",children:"World Inequality Report 2026"})," and its ",(0,n.jsx)(t.a,{href:"https://wir2026.wid.world/www-site/uploads/2025/12/WIR26_TechnicalReport.pdf",children:"Technical Notes"})," (thresholds in PPP euros, 2025 prices, adults 20+, pre-tax national income); ",(0,n.jsx)(t.a,{href:"https://wir2022.wid.world/www-site/uploads/2022/01/Summary_WorldInequalityReport2022_English.pdf",children:"World Inequality Report 2022"}),"; ",(0,n.jsx)(t.a,{href:"https://ideas.repec.org/a/tpr/restat/v97y2015i2p452-460.html",children:"Milanovi\u0107, 2015"}),"; ",(0,n.jsx)(t.a,{href:"https://www.bls.gov/opub/ted/2026/labor-share-at-its-lowest-level-52-8-percent-in-second-quarter-2026.htm",children:"US BLS labor share, Q2 2026"}),"; ",(0,n.jsx)(t.a,{href:"https://www.oxfam.org/en/node/25365",children:"Oxfam, 2026"}),"; Rosling, H., Rosling, O. & Rosling R\xf6nnlund, A.: ",(0,n.jsx)(t.em,{children:"Factfulness"}),", 2018; ",(0,n.jsx)(t.a,{href:"https://www.theguardian.com/commentisfree/2019/jan/29/bill-gates-davos-global-poverty-infographic-neoliberal",children:"Jason Hickel in The Guardian, 2019"}),"; ",(0,n.jsx)(t.a,{href:"https://www.hb.gov.hk/tc/publications/housing/HIF2025.pdf",children:"Housing Bureau: Housing in Figures 2025"}),"; ",(0,n.jsx)(t.a,{href:"https://kpmg.com/us/en/taxnewsflash/news/2026/01/oecd-agreement-pillar-two-side-by-side-package.html",children:"KPMG"})," and ",(0,n.jsx)(t.a,{href:"https://taxnews.ey.com/news/2026-0115-breaking-tax-news-oecd-releases-side-by-side-arrangement-exempting-us-multinationals-from-most-pillar-two-global-minimum-tax-rules",children:"EY"})," on the Pillar Two side-by-side package (January 2026)."]})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,t,o){o.d(t,{R:()=>s,x:()=>r});var n=o(96540);const a={},i=n.createContext(a);function s(e){const t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);